import java.util.*;
import java.io.*;

public class c {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(reader.readLine());
        Circle[] circles = new Circle[n];
        for (int i = 0; i < n; i++) {
            String[] parts = reader.readLine().split(" ");
            int x = Integer.parseInt(parts[0]);
            int y = Integer.parseInt(parts[1]);
            int r = Integer.parseInt(parts[2]);
            circles[i] = new Circle(new Vec(x, y), r);
        }
        List<Vec> points = new ArrayList<>();
        int[] parent = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;
        int totalCount = 1;
        for (int i = 0; i < n; i++) {
            List<Vec> newPoints = new ArrayList<>();
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                Vec[] inters = circles[i].intersect(circles[j]);
                if (inters == null) continue;
                int a = parent[i] = parent[parent[i]];
                int b = parent[j] = parent[parent[j]];
                parent[a] = b;
                for (Vec v : inters) {
                    boolean exists = false;
                    for (Vec e : newPoints) {
                        if (v.equals(e)) {
                            exists = true;
                            break;
                        }
                    }
                    if (!exists) newPoints.add(v);
                }
            }
            totalCount += newPoints.size();
            outer: for (Vec v : newPoints) {
                for (Vec e : points) {
                    if (v.equals(e)) continue outer;
                }
                points.add(v);
            }
        }
        totalCount -= points.size();
        for (int i = 0; i < n; i++) {
            totalCount += 1 - Math.abs(Integer.signum(i - parent[i]));
        }
        System.out.println(totalCount);
    }

    static class Circle {
        Vec c;
        double r;

        public Circle(Vec c, double r) {
            this.c = c;
            this.r = r;
        }

        public Vec[] intersect(Circle o) {
            if (c.equals(o.c)) return null;
            Vec d = o.c.sub(c);
            double dist2 = d.mag2();
            double dist = Math.sqrt(dist2);
            if (r + o.r < dist || r + dist < o.r || o.r + dist < r) return null;
            if (Vec.eq(r + o.r, dist) || Vec.eq(o.r + dist, r))
                return new Vec[] { c.add(d.scale(r / dist)) };
            if (Vec.eq(r + dist, o.r))
                return new Vec[] { c.sub(d.scale(r / dist)) };
            double d1 = (r * r + dist2 - o.r * o.r) / (2 * dist);
            double h = Math.sqrt(r * r - d1 * d1);
            Vec uDir = d.unit();
            Vec rInt = c.add(uDir.scale(d1).add(uDir.rot270().scale(h)));
            Vec lInt = c.add(uDir.scale(d1).add(uDir.rot90().scale(h)));
            return new Vec[] { rInt, lInt };
        }
    }

    static class Vec {
        static final double EPS = 1e-9;
        double x, y;

        public Vec(double x, double y) {
            this.x = x;
            this.y = y;
        }

        public Vec add(Vec o) {
            return new Vec(x + o.x, y + o.y);
        }

        public Vec sub(Vec o) {
            return new Vec(x - o.x, y - o.y);
        }

        public Vec scale(double s) {
            return new Vec(x * s, y * s);
        }

        public double dot(Vec o) {
            return x * o.x + y * o.y;
        }

        public double mag2() {
            return dot(this);
        }

        public double mag() {
            return Math.sqrt(mag2());
        }

        public Vec unit() {
            return scale(1 / mag());
        }

        public Vec rot90() {
            return new Vec(-y, x);
        }

        public Vec rot270() {
            return new Vec(y, -x);
        }

        public boolean equals(Object o) {
            if (!(o instanceof Vec)) return false;
            Vec v = (Vec) o;
            return eq(x, v.x) && eq(y, v.y);
        }

        public String toString() {
            return "(" + String.format("%.2f", x) + ", " + String.format("%.2f", y) + ")";
        }

        static boolean eq(double a, double b) {
            return Math.abs(a - b) < EPS;
        }
    }
}
